files.manifest.json:
{
  "name": "answer_industry_competitor_question",
  "kind": "workflow",
  "description": "Answers questions about companies, products and competitors in a given industry from published knowledge, with sources and uncertainty.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"industry\":{\"type\":\"string\"},\"company\":{\"type\":\"string\"},\"focus\":{\"type\":\"string\"},\"question\":{\"type\":\"string\"}},\"required\":[\"industry\",\"question\"]}",
    "out": "output of s1"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "answer_industry_competitor_question_llm",
      "foreach": null,
      "inputs": [
        {
          "param": "industry",
          "source": "$input.industry"
        },
        {
          "param": "company",
          "source": "$input.company"
        },
        {
          "param": "focus",
          "source": "$input.focus"
        },
        {
          "param": "question",
          "source": "$input.question"
        }
      ]
    }
  ],
  "output_step": "s1",
  "permissions": {
    "net": [],
    "llm": true
  },
  "budget": {
    "max_tokens_per_run": 6000
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "answer_industry_competitor_question_llm@v1"
    ]
  },
  "example_input": "{\"industry\":\"database software\",\"company\":\"MongoDB\",\"focus\":\"main competitors, products and market positioning\",\"question\":\"Who are MongoDB's main competitors in the database software industry and how do their offerings compare?\"}",
  "purpose": "make a bot to gather information in the database software industry and find out details about competitors",
  "version": 1,
  "headline": "{answer}",
  "examples": [
    "Who are Snowflake's biggest competitors?",
    "How does PostgreSQL compare to MySQL in the market?",
    "What are Oracle's strengths against cloud database vendors?"
  ],
  "voice": "witch",
  "manual_minutes": 45.0,
  "manual_basis": "Research MongoDB's competitors via web search, review product documentation and market reports, compile competitive positioning analysis with feature/pricing comparisons in spreadsheet."
}

files.test_report.json:
{
  "passed": true,
  "summary": "end-to-end run succeeded and acceptance check passed",
  "output": "{\"answer\": \"MongoDB is the leading document-oriented NoSQL database, sold mainly through its Atlas managed cloud service alongside self-managed Enterprise Advanced. Its closest competitors are cloud-provider document databases such as Amazon DocumentDB (MongoDB-compatible API) and Azure Cosmos DB (which offers a MongoDB API), plus other NoSQL options like Couchbase and Redis. It also competes with relational incumbents and open-source databases such as Oracle Database and PostgreSQL, which now support JSON documents and appeal to teams wanting a single general-purpose system. MongoDB positions itself on developer productivity, flexible schema, multi-cloud availability across AWS, Azure and Google Cloud, and a broadening platform including search, vector search, and analytics, whereas hyperscaler offerings emphasize tight integration with their own ecosystems and relational databases emphasize maturity and SQL tooling.\", \"competitors\": [\"Amazon DocumentDB\", \"Azure Cosmos DB\", \"Couchbase\", \"Oracle Database\", \"PostgreSQL\", \"Redis\"], \"sources\": [\"MongoDB 10-K filings\", \"vendor product documentation\", \"general public knowledge\"], \"uncertainty\": \"Knowledge has a training cutoff, so recent product launches, pricing and market share shifts may not be reflected. No exact market share figures are given because they vary by analyst and year.\"}"
}
